select id, session_id, user_id, role, content, create_time, remark
from im_chat_message

    and user_id = #{userId}
    and session_id = #{sessionId}
    and role = #{role}
    and content like concat('%', #{keyword}, '%')

order by create_time desc, id desc

select id, session_id, user_id, role, content, create_time, remark
from im_chat_message
where id = #{id}
